  // Owner-authorized private copied-site policy only. Ordinary player protection is rechecked below.
  var bounds=ConstructionService.bounds(project);for(int x=((int)bounds.minX)>>4;x<=((int)bounds.maxX)>>4;x++)for(int z=((int)bounds.minZ)>>4;z<=((int)bounds.maxZ)>>4;z++){var at=new BlockPos(x*16,home.getY(),z*16);ClaimRuntimeTests.ftbUnclaim(h.getLevel(),at);ClaimRuntimeTests.ftbClaim(p,at);ClaimRuntimeTests.opacClaim(h.getLevel(),p.getUUID(),at);}ClaimRuntimeTests.publicResidentAccess(h.getLevel(),p.getUUID());LibraryServiceRuntime.counter(p);BlacksmithRepairRuntime.near(admin,home);server.getPlayerList().op(admin.getGameProfile());long xp=store.professions(id).track(Profession.LIBRARIAN).xp();var slots=new ArrayList<Integer>();for(int i=0;i<36&&slots.size()<4;i++)if(p.getInventory().getItem(i).isEmpty())slots.add(i);h.assertTrue(slots.size()==4,"Raw glyph fixture preserves old equipment and earned items");
