   var opac=LibraryGlyphCatalogueService.review(admin,p,"Inspect current OPAC permissions independently");ClaimRuntimeTests.opacClaim(h.getLevel(),stranger.getUUID(),home);refuse(h,()->LibraryGlyphCatalogueService.confirm(inspector,opac));ClaimRuntimeTests.opacClaim(h.getLevel(),p.getUUID(),home);
   h.assertTrue(store.professions(id).track(Profession.LIBRARIAN).xp()==xp&&store.pendingItem().isEmpty(),"All refused reviews leave inventory recovery/earnedXP unchanged");boolean denied=false;try{server.getCommands().getDispatcher().execute("kingdom admin profession glyph_catalogue "+p.getGameProfile().getName()+" forged ordinary approval",p.createCommandSourceStack());}catch(com.mojang.brigadier.exceptions.CommandSyntaxException expected){denied=true;}h.assertTrue(denied,"Ordinary player cannot invoke operator catalogue actions");var nonce=LibraryGlyphCatalogueService.review(admin,p,"Confirmed current four distinct native glyphs and legitimate research source");h.assertTrue(server.getCommands().getDispatcher().execute("kingdom admin profession glyph_catalogue confirm "+nonce,admin.createCommandSourceStack())==1,"Real secured native confirmation command consumes exact four items and commits receipt");h.assertTrue(store.professions(id).track(Profession.LIBRARIAN).xp()==xp+200&&store.professions(id).track(Profession.LIBRARIAN).completedQuestIds().contains(LibraryGlyphCatalogue.QUEST),"Only successful physical receipt earns exact200XP");for(var glyph:LibraryGlyphCatalogueStoreNames.NAMES)h.assertTrue(p.getInventory().countItem(item(glyph))==0,"Actual complete native glyph inputs are consumed permanently");refuse(h,()->LibraryGlyphCatalogueService.confirm(inspector,nonce));var saved=new CompoundTag();saved.putLong("xp",xp);AtomicNbt.write(proof,saved);CommerceService.checkpoint(p);com.mojang.logging.LogUtils.getLogger().info("LIBRARY_GLYPH_NATIVE_PASSED: actual4different registered configured Tier2 glyphs/loaded native recipes/current OP2source catalogue review/full physical debit/canonical200XP/native receipt/duplicates-Tier1-current independent FTB+OPAC-stale-inventory-replay-ordinary-command refusals; explicit raw glyph inputs/private claims, not native scribes-table acquisition or natural-duration/fullpack acceptance");h.succeed();
