 static final class LibraryGlyphCatalogueStoreNames {static final List<String> NAMES=List.of("conjure_water","crush","grow","smelt");}
 static Item item(String id){return BuiltInRegistries.ITEM.get(ResourceLocation.parse("ars_nouveau:glyph_"+id));}
 interface Action{void run()throws Exception;}
 static void refuse(GameTestHelper h,Action action)throws Exception{boolean denied=false;try{action.run();}catch(IllegalArgumentException|IllegalStateException expected){denied=true;}h.assertTrue(denied,"Changed or unauthorized catalogue must refuse");}
 static ServerPlayer adminFor(ServerPlayer p,UUID owner){return p.server.getPlayerList().getPlayer(owner);}
 static ServerPlayer playerFor(ServerPlayer p){return p;}
 static void verifyIrons(GameTestHelper h,ServerPlayer p)throws Exception{
  if(!net.neoforged.fml.ModList.get().isLoaded("irons_spellbooks"))return;h.assertTrue(net.neoforged.fml.ModList.get().getModContainerById("irons_spellbooks").orElseThrow().getModInfo().getVersion().toString().equals("1.21.1-3.16.3"),"Exact approved Irons3.16.3 artifact is loaded");
  var registry=Class.forName("io.redspace.ironsspellbooks.api.registry.SpellRegistry");var spell=Class.forName("io.redspace.ironsspellbooks.api.spells.AbstractSpell");var rarity=Class.forName("io.redspace.ironsspellbooks.api.spells.SpellRarity");var data=Class.forName("io.redspace.ironsspellbooks.api.spells.SpellData");var container=Class.forName("io.redspace.ironsspellbooks.api.spells.ISpellContainer");var rare=rarity.getField("RARE").get(null);var scroll=BuiltInRegistries.ITEM.get(ResourceLocation.parse("irons_spellbooks:scroll"));h.assertTrue(Class.forName("io.redspace.ironsspellbooks.item.Scroll").isInstance(scroll),"Actual registered native scroll class is present");var candidates=new TreeMap<String,String>();
  for(var candidate:(List<?>)registry.getMethod("getEnabledSpells").invoke(null)){if(!(Boolean)spell.getMethod("allowCrafting").invoke(candidate)||!(Boolean)spell.getMethod("canBeCraftedBy",net.minecraft.world.entity.player.Player.class).invoke(candidate,p))continue;int level=(Integer)spell.getMethod("getMinLevelForRarity",rarity).invoke(candidate,rare);if(level<1||level>(Integer)spell.getMethod("getMaxLevel").invoke(candidate))continue;var stack=new ItemStack(scroll);container.getMethod("createScrollContainer",spell,int.class,ItemStack.class).invoke(null,candidate,level,stack);var nativeContainer=container.getMethod("get",ItemStack.class).invoke(null,stack);var nativeData=container.getMethod("getSpellAtIndex",int.class).invoke(nativeContainer,0);if(!data.getMethod("getRarity").invoke(nativeData).equals(rare))continue;var key=spell.getMethod("getSpellResource").invoke(candidate).toString();if(candidates.size()<4)candidates.put(key,stack.save(p.registryAccess()).toString());}
  h.assertTrue(candidates.size()==4,"Actual enabled/craftable native spell IDs have four genuine RARE scroll component variants");com.mojang.logging.LogUtils.getLogger().info("LIBRARY_IRONS_API_VALIDATED: exact3.16.3 registered Scroll/ISpellContainer/SpellData native RARE/current enabled craftable IDs and serialized native components {}. j05 remains disabled; this API check is not acquisition/quest acceptance.",candidates);
 }

